/**
 * Combines two `RedBlackTree` objects representing overlap clients,
 * modifying the first tree in-place if it exists, or cloning the second tree.
 */
function combineRBTrees(
	aTree: RedBlackTree<number, IOverlapClient> | undefined,
	bTree: RedBlackTree<number, IOverlapClient> | undefined,
): RedBlackTree<number, IOverlapClient> | undefined {
	if (aTree) {
		if (bTree) {
			bTree.map((bProp: Property<number, IOverlapClient>) => {
				const aProp = aTree.get(bProp.key);
				if (aProp) {
					aProp.data.seglen += bProp.data.seglen;
				} else {
					aTree.put(bProp.data.clientId, { ...bProp.data });
				}
				return true;
			});
		}
		return aTree;
	} else {
		return cloneOverlapRemoveClients(bTree);
	}
}

/**
 * Combines the `overlapRemoveClients` field of two `PartialSequenceLength` objects,
 * modifying the first PartialSequenceLength's bookkeeping in-place.
 *
 * Combination is performed additively on `seglen` on a per-client basis.
 */
export function combineOverlapClients(a: PartialSequenceLength, b: PartialSequenceLength) {
	a.overlapRemoveClients = combineRBTrees(a.overlapRemoveClients, b.overlapRemoveClients);
	a.overlapObliterateClients = combineRBTrees(
		a.overlapObliterateClients,
		b.overlapObliterateClients,
	);
}

